/* Generated by installer/theme_css.py from shell/themes/resolved-themes.json.
   Theme: dark · text scale 1 ·
   motion ·
   translucent.
   Every value here comes from the resolved theme; nothing is decided in Python. */

/* ---------------------------------------------------------------- surface */

window.bunny-setup,
.bunny-setup {
  background-color: #080B12;
  color: #F7F8FA;
  font-size: 12px;
  font-weight: 400;
  font-family: inherit;
}

.bunny-setup-column {
  padding: 32px;
  min-width: 304px;
}

/* §5: the opening scene is the Companion on a light ground with almost nothing
   else on it, so the greeting surface gets its own generous measure. */
.bunny-setup-welcome .bunny-setup-column {
  padding: 48px;
}

/* ------------------------------------------------------------------- type */

.bunny-setup-heading {
  font-size: 19px;
  font-weight: 700;
  font-family: inherit;
  color: #F7F8FA;
  margin-bottom: 12px;
}

.bunny-setup-says {
  font-size: 14px;
  font-weight: 600;
  font-family: inherit;
  color: #F7F8FA;
}

.bunny-setup-label {
  font-size: 12px;
  font-weight: 400;
  font-family: inherit;
  color: #F7F8FA;
}

.bunny-setup-help {
  font-size: 11px;
  font-weight: 400;
  font-family: inherit;
  color: #B4BAC6;
  margin-top: 2px;
}

.bunny-setup-required {
  color: #8F96A4;
}

.bunny-setup-value {
  font-size: 12px;
  font-weight: 400;
  font-family: inherit;
  color: #F7F8FA;
}

.bunny-setup-advanced,
.bunny-setup-advanced-line {
  font-size: 11px;
  font-weight: 400;
  font-family: monospace;
  color: #8F96A4;
}

.bunny-setup-disclosure {
  font-size: 11px;
  font-weight: 400;
  font-family: inherit;
  color: #A78BFA;
}

/* The accessible announcement. Present in the widget tree with its text set,
   never drawn: GTK reads it to Orca and gives it no allocation. §9 asks for an
   equivalent, and an equivalent that took space would be a duplicate. */
.bunny-setup-announcement {
  font-size: 10px;
  font-weight: 500;
  font-family: inherit;
  color: #8F96A4;
}

/* --------------------------------------------------------------- controls */

.bunny-setup-field {
  margin-bottom: 20px;
}

entry.bunny-setup-entry {
  font-size: 12px;
  font-weight: 400;
  font-family: inherit;
  color: #F7F8FA;
  background-color: rgba(27, 31, 45, 0.65);
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  padding: 8px 12px;
  transition: border-color 120ms ease-out;
}

entry.bunny-setup-entry:disabled {
  color: #8F96A4;
}

/* A field the installer backend rejected. Colour is never the only signal —
   the message text is a sibling label, so this reads correctly in high contrast
   and to a screen reader alike. */
entry.bunny-setup-entry.bunny-setup-invalid {
  border-color: #EF4444;
}

.bunny-setup-option {
  padding: 8px 12px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  border-radius: 12px;
  background-color: rgba(17, 21, 32, 0.72);
  margin-bottom: 4px;
  transition: background-color 120ms ease-out;
}

.bunny-setup-option:hover {
  background-color: rgba(255, 255, 255, 0.07);
}

.bunny-setup-option:selected,
.bunny-setup-option:checked {
  background-color: rgba(139, 92, 246, 0.30);
  color: #FFFFFF;
}

/* Visible and unselectable, never hidden. A disk that vanishes from the list is
   a consequence hidden by omission — see storage_screen in setup_view.py. */
.bunny-setup-option-unavailable {
  color: #8F96A4;
  background-color: #080B12;
}

.bunny-setup-option-label {
  font-size: 12px;
  font-weight: 400;
  font-family: inherit;
}

.bunny-setup-option-note {
  font-size: 10px;
  font-weight: 500;
  font-family: inherit;
  color: #B4BAC6;
}

/* --------------------------------------------------------------- warnings */

.bunny-setup-warning {
  padding: 12px;
  border-radius: 18px;
  margin-bottom: 12px;
  border: 1px solid rgba(255, 255, 255, 0.06);
}

.bunny-setup-warning-info {
  background-color: rgba(17, 21, 32, 0.72);
  color: #F7F8FA;
}

.bunny-setup-warning-caution {
  background-color: rgba(17, 21, 32, 0.72);
  color: #F7F8FA;
  border-color: #F59E0B;
}

/* §11: destructive consequences are never softened. This is the only role that
   uses the danger colour as a border and the only one with a raised weight, so
   the treatment means exactly one thing wherever it appears. */
.bunny-setup-warning-danger {
  background-color: rgba(17, 21, 32, 0.72);
  color: #F7F8FA;
  border: 2px solid #EF4444;
}

.bunny-setup-warning-danger .bunny-setup-warning-text {
  font-size: 14px;
  font-weight: 600;
  font-family: inherit;
  color: #EF4444;
}

.bunny-setup-warning-glyph {
  color: #EF4444;
  margin-right: 8px;
}

/* --------------------------------------------------------------- progress */

.bunny-setup-stage {
  padding: 4px 0;
  font-size: 12px;
  font-weight: 400;
  font-family: inherit;
  color: #8F96A4;
}

.bunny-setup-stage-done {
  color: #22C55E;
}

.bunny-setup-stage-active {
  color: #F7F8FA;
  font-weight: 600;
}

.bunny-setup-stage-glyph {
  margin-right: 8px;
}

/* ---------------------------------------------------------------- actions */

button.bunny-setup-action {
  font-size: 11px;
  font-weight: 600;
  font-family: inherit;
  padding: 8px 20px;
  border-radius: 12px;
  border: 1px solid rgba(255, 255, 255, 0.06);
  background-color: rgba(27, 31, 45, 0.65);
  color: #F7F8FA;
  transition: background-color 220ms ease-out;
}

button.bunny-setup-action-primary {
  background-color: #7C3AED;
  color: #FFFFFF;
  border-color: #7C3AED;
}

button.bunny-setup-action-safe {
  background-color: rgba(27, 31, 45, 0.65);
  color: #F7F8FA;
}

button.bunny-setup-action-quiet {
  background-color: transparent;
  border-color: transparent;
  color: #A78BFA;
}

/* The button that erases a disk. Distinct from primary, so that the forward
   action on an ordinary screen and the destructive action on the confirmation
   screen can never be the same shape in the same place. */
button.bunny-setup-action-danger {
  background-color: #EF4444;
  color: #FFFFFF;
  border-color: #EF4444;
}

button.bunny-setup-action:disabled {
  color: #8F96A4;
  background-color: rgba(17, 21, 32, 0.72);
  border-color: rgba(255, 255, 255, 0.06);
}

button.bunny-setup-action:focus-visible {
  outline: 2px solid #A78BFA;
  outline-offset: 2px;
}
entry.bunny-setup-entry:focus-visible {
  outline: 2px solid #A78BFA;
  outline-offset: 2px;
}
.bunny-setup-option:focus-visible {
  outline: 2px solid #A78BFA;
  outline-offset: 2px;
}
checkbutton.bunny-setup-toggle:focus-visible {
  outline: 2px solid #A78BFA;
  outline-offset: 2px;
}
switch.bunny-setup-toggle:focus-visible {
  outline: 2px solid #A78BFA;
  outline-offset: 2px;
}

/* -------------------------------------------------------------- companion */

.bunny-setup-companion {
  margin-bottom: 32px;
}

.bunny-setup-figure {
  min-width: 300px;
  min-height: 300px;
  border-radius: 20px;
}

